INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0185', 'D-OP', 'DG-NON', 'Owner ruling. Work-product inclusion and the disposition of a retired corpus are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable. DR-2026-08-19 §1.5 named this consequence specifically and demanded it be decided ''as its own decision, before items is touched''.', 'Restore the 83 archived code/standard leads as research_code_leads, executing D-0181 rather than superseding it.', 'ADOPTED by owner ruling 2026-09-02, choosing option A of three put to the owner.', 'The 2026-09-01 base-and-research-only ruling emptied jurisdictional_values as a side effect of deleting the item layer, because its item_code column is NOT NULL REFERENCES items. Neither quoted ruling named the table, and DR-2026-08-19 §1.5 had demanded the opposite sequencing: decide it separately, ''it must not be collateral damage''. It was collateral damage. D-0181 of 2026-08-31 had already called these rows research and already named the successor table, so restoring them EXECUTES that decision. Measured: the 109 archived records carry three non-null columns and collapse to 83 distinct (jurisdiction, standard_name) leads across 12 jurisdictions; the other 26 are the same standard restated per design parameter. 100% of surviving information is item-independent, so the only thing dropped is the item link -- the thing the ruling says must not exist -- and it survives in the archived filenames for provenance.', '2026-09-02 19:10', 'jordanelias', 'human/none/none', 0, 'ACTIVE', 'NA', '[]', '["D-0181"]', '["decisions/DR-2026-09-02-restore-research-code-leads.md", "scripts/migrations/066_research_code_leads.sql", "scripts/migrations/data_20260902191029_2026-09-02-restore-research-code-leads.sql"]', '["Confirm the deletion and record it as superseding D-0181 -- rejected by the owner: ~72 of the 83 leads exist nowhere else and would die with the archive.", "Merge them into source_locators -- rejected: that store already carries 24 rows holding both a standard_number and a DOI, and a standard has no DOI. That misalignment is what made REF-00037 carry a PLoS ONE DOI against a RIBA housing-guide title and falsely block an admission on 2026-09-01."]', 'OWED, AND DELIBERATELY NOT DONE HERE. jurisdictional_values is left in place and empty rather than dropped, because v_code_floor_only reads it and CLAUDE.md holds a cross-stage view to be the most protected object in the schema -- the pointer rule 5''s point-don''t-copy actually means in SQL. That view joins on item_code, a column the owner ruled out of existence, so what it becomes is its own question. ALSO OWED: 11 of the 83 standards also appear in source_locators.standard_number and are reconciliation debt, not a licence to duplicate; and research_code_leads.jurisdiction carries NO CHECK because the vocabulary''s nearest home, lang_jur_map, lacks two of the twelve values restored (GB and ISO, the latter a standards body rather than a country) -- registering a real jurisdiction vocabulary and pointing both at it is owed, not faked. D-0181''s own note is now stale: it says the rename lands in ''the parked migration 065'', but slot 065 was consumed by the four-lens link table on 2026-09-01.', '2026-09-02 19:10', 'session_2026-09-02-owner-rulings-restore-sweep-strike', '2026-09-02 19:10', 'session_2026-09-02-owner-rulings-restore-sweep-strike');
INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0186', 'D-OP', 'DG-NON', 'Owner ruling. What the project publishes is work-product inclusion, DG-NON under governance/decision-protocol.md.', 'Finish the render sweep: archive the site surfaces that publish the deleted item layer.', 'ADOPTED by owner ruling 2026-09-02, choosing option B of two put to the owner.', 'The 2026-09-01 retraction deleted site/specs and stopped, leaving site/populations publishing 172 links across 79 item codes and both index pages pointing into a directory that no longer existed. No gate caught it because validate_cross_refs treats site/ as REFERENCE_ONLY. DR-2026-08-19 §1.2 had predicted exactly this: ''archiving the items rows quarantines none of this -- a researcher who greps the repository for their slug will meet the old answer before they have logged their first search.'' Leaving the surface half-swept was the one disposition ruled out: neither frozen nor swept, just broken.', '2026-09-02 19:15', 'jordanelias', 'human/none/none', 0, 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-09-02-finish-the-render-sweep.md", "_archived/site/"]', '["Treat site/ as a frozen reference surface and restore site/specs -- rejected by the owner: it keeps publishing determinations the data no longer holds.", "Leave the state as it was -- ruled out before the choice was put: half a rendered surface is not a disposition."]', 'CORRECTS AN EARLIER SESSION ERROR. The 93 spec pages were deleted outright on 2026-09-01. CLAUDE.md §1 holds that git history is the archive for CODE and _archived/ is the right home for retired CONTENT; rendered pages are content. They are restored to _archived/site/specs/, which also makes the archived index.html''s relative links resolve, and root index.html''s six links are repointed there. UNEXPLAINED, STATED RATHER THAN TIDIED: two pages, [cross-cutting].html and [unassigned].html, arrived in the restore set. They are real rendered pages appearing nowhere in git history -- 93 were deleted and 93 existed at befaa29^. Kept because they are content, but the mechanism by which they entered the set was not reconstructed and no mechanism was invented. OWED: root index.html still states the determination ''Corridor Clear Width (>=1200 mm Minimum on All Primary Routes)'' as fact on its front page. Rewriting the landing page''s framing is mission-level content and was not done here.', '2026-09-02 19:15', 'session_2026-09-02-owner-rulings-restore-sweep-strike', '2026-09-02 19:15', 'session_2026-09-02-owner-rulings-restore-sweep-strike');
INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0187', 'D-DOCT', 'DG-NON', 'Owner ruling amending a RATIFIED Decision Record. CLAUDE.md rule 0: a live owner statement supersedes every prior ratified record it touches, on contact.', 'Strike DR-2026-08-19 §12.1 step 2''s item-frame query; replace it with an ICF-first frame pull.', 'ADOPTED by owner ruling 2026-09-02.', 'The instrument contradicted itself at the point it was most trusted. §1.4 rule 1 says a slug is authored from the ICF/access-need frame first and the item list consulted for coverage ''never to supply one''; rule 2 says ''No value crosses'' from an item name into a search_executions or search_candidates row. §12.1 step 2 ordered the frame pulled from items. A session obeying the runbook therefore broke the quarantine, and on 2026-09-01 one did: FRAME.md was derived from items and the item values ''22 N'' and ''PTV >=36'' reached agonist queries. The step is also inert three times over -- items is empty, and item_axis_links and item_population_links were dropped by migration 065.', '2026-09-02 19:16', 'jordanelias', 'human/none/none', 0, 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-09-02-strike-the-item-frame-pull.md", "decisions/DR-2026-08-19-research-restart-operative-instrument.md"]', '["Amend \u00a71.4 instead so the item frame becomes lawful -- rejected: \u00a71.4 is the quarantine, and the measured harm ran the other way.", "Leave both and rely on sessions to notice -- rejected: one did not, which is why this exists."]', 'Struck in place with the original text preserved, per the D-0181 precedent that editing a ratified DR''s runbook is done under explicit owner ruling with the struck text kept in the record. THE REPLACEMENT STATES TWO GAPS RATHER THAN PAPERING OVER THEM, both created by the 2026-09-01 retraction and neither repaired: term_item_links was the only route from terms and term_aliases (88 and 2,382 rows) to a research subject and is now empty, so R11''s terms_used has no slug route; and slugs.serves_axes is populated on 1 of 106 rows, so the cross-product the step pulls is generic rather than slug-specific. A runbook step that cannot execute is the defect this strike removes, so the step says only what is actually reachable.', '2026-09-02 19:16', 'session_2026-09-02-owner-rulings-restore-sweep-strike', '2026-09-02 19:16', 'session_2026-09-02-owner-rulings-restore-sweep-strike');